  "paths": {
    "/customers/{customerId}/associates": {
      "get": {
        "tags": [
          "Customers"
        ],
        "summary": "Get all associates for a customer",
        "operationId": "getAssociatesByCustomer",
        "parameters": [
          {
            "name": "customerId",
            "in": "path",
            "description": "ID of the customer",
            "required": true,
            "style": "simple",
            "explode": false,
            "schema": {
              "type": "string"
            }
          },
          {
            "name": "searchCriteria",
            "in": "query",
            "required": true,
            "style": "form",
            "explode": true,
            "schema": {
              "$ref": "#/components/schemas/customercompliance.AssociateSearchCriteria"
            }
          }
        ],
        "responses": {
          "200": {
            "description": "OK",
            "content": {
              "application/json": {
                "schema": {
                  "$ref": "#/components/schemas/customercompliance.AssociatePageResponse"
                }
              }
            }
          },
          "400": {
            "description": "Invalid Parameters",
            "content": {
              "*/*": {
                "schema": {
                  "type": "array",
                  "items": {
                    "$ref": "#/components/schemas/customercompliance.MessageResponse"
                  }
                }
              }
            }
          },
          "403": {
            "description": "Incorrect permissions",
            "content": {
              "application/json": {
                "schema": {
                  "$ref": "#/components/schemas/customercompliance.AssociatePageResponse"
                }
              }
            }
          }
        },
        "security": [
          {
            "HMAC": []
          },
          {
            "TOKEN": []
          }
        ]
      }
    }
  },
  "components": {
    "schemas": {
      "customercompliance.AssociateAdditionalIdentifier": {
        "type": "object",
        "description": "Additional personal identifier",
        "properties": {
          "type": {
            "type": "string",
            "description": "Type of additional personal identifier",
            "enum": [
              "BSN"
            ]
          },
          "value": {
            "type": "string",
            "description": "Identifier value",
            "minLength": 1
          }
        },
        "required": [
          "type",
          "value"
        ]
      },
      "customercompliance.AssociateSearchCriteria": {
        "type": "object",
        "properties": {
          "additionalIdentifier": {
            "$ref": "#/components/schemas/customercompliance.AssociateAdditionalIdentifier",
            "description": "Additional personal identifier"
          },
          "page": {
            "type": "integer",
            "format": "int32",
            "description": "Page to fetch (0 indexed)",
            "minimum": 0
          },
          "size": {
            "type": "integer",
            "format": "int32",
            "description": "Size of page to fetch",
            "maximum": 500
          }
        }
      },
      "customercompliance.MessageResponse": {
        "type": "object",
        "properties": {
          "field": {
            "type": "string"
          },
          "code": {
            "type": "string",
            "enum": [
              "GENERAL",
              "BUSINESSRULE",
              "MFASTATUS",
              "MFAERROR",
              "MFATIMEOUT",
              "MFADEVICEMM",
              "MFAMESSAGEINVALID",
              "NOTFOUND",
              "DUPLICATE",
              "INVALID",
              "CONNECTION",
              "RETRY",
              "RATELIMIT",
              "PERMISSION",
              "NOTACCEPTABLE",
              "MFAVERIFICATION",
              "TOKENEXPIRED"
            ]
          },
          "errorCode": {
            "type": "string"
          },
          "message": {
            "type": "string"
          },
          "sourceService": {
            "type": "string"
          }
        }
      },
      "customercompliance.AssociatePageResponse": {
        "type": "object",
        "properties": {
          "content": {
            "type": "array",
            "description": "List of responses on the current page",
            "items": {
              "$ref": "#/components/schemas/customercompliance.AssociateResponse"
            }
          },
          "size": {
            "type": "integer",
            "format": "int32",
            "description": "Page size"
          },
          "totalSize": {
            "type": "integer",
            "format": "int64",
            "description": "Total count"
          },
          "page": {
            "type": "integer",
            "format": "int32",
            "description": "Current page number, 0 based; i.e first-page = 0, second-page = 1"
          },
          "totalPages": {
            "type": "integer",
            "format": "int32",
            "description": "Total pages"
          }
        }
      },
      "customercompliance.AssociateResponse": {
        "type": "object",
        "properties": {
          "id": {
            "type": "string",
            "description": "Associate bid"
          }
        }
      }
    },
    "securitySchemes": {
      "modulo_security": {
        "type": "apiKey",
        "name": "Authorization",
        "in": "header"
      },
      "TOKEN": {
        "type": "apiKey",
        "name": "Authorization",
        "in": "header"
      }
    }
  },
  "x-readme": {
    "proxy-enabled": false
  }
}
